15	// Add float suffix to the intrinsics, CUDA fast math.
16	using tirx::FLowerIntrinsic;
17	using namespace ffi;
18	
19	struct CUDAMath {
20	  std::string operator()(DataType t, std::string name) const {
21	    if (t.is_float()) {
22	      switch (t.bits()) {
23	      case 64:
24	        return name;
25	      case 32:
26	        return name + 'f';
27	      case 16: {
28	        if (name == "fabs") {
29	          return "__habs";
30	        } else if (name == "round") {
31	          return "hrint";
32	        } else {
33	          return "h" + name;
34	        }
35	      }
