37	        return "";
38	      }
39	    } else if (t.is_bfloat16()) {
40	      if (name == "fabs") {
41	        return "__habs";
42	      } else if (name == "round") {
43	        return "hrint";
44	      } else {
45	        return "h" + name;
46	      }
47	    } else if (t.is_int() || t.is_uint()) {
48	      switch (t.bits()) {
49	      case 32:
50	        return "__" + name;
51	      case 64:
52	        return "__" + name + "ll";
53	      default:
54	        return "";
55	      }
56	    }
57	    return "";
58	  }
59	};
60	
61	struct CUDAFastMath : public CUDAMath {
62	  std::string operator()(DataType t, std::string name) const {
63	    if (t.is_float() && t.bits() == 32) {
64	      return "__" + name + 'f';
65	    } else {
66	      return CUDAMath::operator()(t, name);
67	    }
68	    return "";
69	  }
70	};
71	
72	struct CUDAFastMathTan : public CUDAMath {
73	  std::string operator()(DataType t, std::string name) const {
74	    if (t.is_float()) {
75	      switch (t.bits()) {
76	      case 64:
77	        return name;
78	      // `__tanf` seems to produce some values too deviant from numpy tan
79	      // version. So, let's use just `tanf` instead.
80	      case 32:
81	        return name + 'f';
82	      case 16:
83	        return 'h' + name;
84	      default:
85	        return "";
86	      }
87	    }
88	    return "";
89	  }
90	};
91	
92	struct CUDAPopcount {
