108	struct CUDAWarpIntrinsic {
109	  const Op operator()(DataType t, const Op &orig_op) const {
110	    if (orig_op.same_as(builtin::tvm_warp_shuffle())) {
111	      return Op::Get("tirx.cuda.__shfl_sync");
112	    } else if (orig_op.same_as(builtin::tvm_warp_shuffle_up())) {
113	      return Op::Get("tirx.cuda.__shfl_up_sync");
114	    } else {
115	      ICHECK(orig_op.same_as(builtin::tvm_warp_shuffle_down()));
116	      return Op::Get("tirx.cuda.__shfl_down_sync");
117	    }
118	  }
119	};
