121	static PrimExpr DispatchCUDAWarpActiveMask(const PrimExpr &e) {
122	  const CallNode *call = e.as<CallNode>();
123	  return Call(call->dtype, Op::Get("tirx.cuda.__activemask"), call->args,
124	              call->annotations);
