1	/*!
2	 * \file intrin_rule_hip.cc
3	 * \brief HIP intrinsic rules.
4	 */
5	#include "support/check.h"
6	#include <tvm/ir/cast.h>
7	#include <tvm/tirx/builtin.h>
8	#include <tvm/tirx/op_attr_types.h>
9	
10	#include "target/intrin_rule.h"
11	
12	namespace tvm {
13	namespace codegen {
14	namespace intrin {
15	// Add float suffix to the intrinsics, HIP fast math.
16	using tirx::FLowerIntrinsic;
17	
18	// HIP has no vectorized fp32 math builtins: exp2f etc. are scalar
19	// (float exp2f(float)), with no exp2(float4)/float2 overload (only half2 has
20	// packed intrinsics like h2exp2). So HIPMath/FloatSuffix return no name for a
21	// vector dtype and DispatchPureExtern leaves the op unlowered, which the HIP
22	// source codegen then can't print. Resolve the extern name from the *element*
23	// type instead and emit a vector call_pure_extern; CodeGenTileLangHIP::
24	// PrintCallExtern lowers it to one scalar call per lane and stores via
25	// PrintVecElemStore, which is correct for HIP's packed carrier types
26	// (float32x8 -> ulonglong4, float16x4 -> uint2, etc.). Scalars are unchanged.
27	template <typename T, bool dtype_from_arg = false>
28	inline PrimExpr DispatchPureExternScalarized(const PrimExpr &e) {
29	  const CallNode *call = e.as<CallNode>();
30	  ICHECK(call != nullptr);
31	  DataType dtype = dtype_from_arg ? call->args[0].dtype() : call->dtype;
32	  if (!dtype.is_vector()) {
33	    return DispatchPureExtern<T, dtype_from_arg>(e);
34	  }
35	  const OpNode *op = call->op.as<OpNode>();
36	  ICHECK(op != nullptr);
37	  std::string name = T()(dtype.element_of(), op->name.substr(5));
38	  if (name.empty()) {
39	    return e;
40	  }
41	  ffi::Array<PrimExpr> new_args = {StringImm(name)};
42	  for (const auto &arg : call->args) {
43	    new_args.push_back(arg);
44	  }
45	  return Call(call->dtype, builtin::call_pure_extern(), new_args,
46	              call->annotations);
47	}
48	
49	struct HIPMath {
50	  std::string operator()(DataType t, std::string name) const {
51	    if (t.is_float()) {
52	      switch (t.bits()) {
53	      case 64:
54	        return name;
55	      case 32:
56	        return name + 'f';
57	      case 16: {
58	        if (name == "fabs") {
59	          return "__habs";
60	        } else if (name == "round") {
61	          return "hrint";
62	        } else {
63	          return "h" + name;
64	        }
65	      }
66	      default:
67	        return "";
68	      }
